-- Hrušovanská liga: application access is exclusively through server-side service role.
create table if not exists public.darts_players (
  id bigint primary key, name text not null, email text, active boolean not null default true,
  role text not null default 'PLAYER', phone text, birth_date date,
  preferred_days boolean[] not null default array[false,false,false,false,false,false,false]
);
create unique index if not exists darts_players_email_idx on public.darts_players (lower(email)) where email is not null and email <> '';
create table if not exists public.darts_competitions (id bigint primary key, name text not null, start_date date, end_date date, active boolean not null default false);
create table if not exists public.darts_locations (id bigint primary key, name text not null, address text, city text, active boolean not null default true);
create table if not exists public.darts_boards (id bigint primary key, location_id bigint references public.darts_locations(id), name text, active boolean not null default true);
create table if not exists public.darts_opening_hours (id bigint primary key, location_id bigint references public.darts_locations(id), day_of_week integer, open_time text, close_time text);
create table if not exists public.darts_blocked_days (id bigint primary key, location_id bigint references public.darts_locations(id), board_id bigint references public.darts_boards(id), blocked_from timestamp, blocked_to timestamp, reason text);
create table if not exists public.darts_matches (
  id bigint primary key, competition_id bigint references public.darts_competitions(id), home_player bigint references public.darts_players(id), away_player bigint references public.darts_players(id), match_date timestamp, status text, approved_home boolean not null default false, approved_away boolean not null default false, score text, board_id bigint references public.darts_boards(id), location_id bigint references public.darts_locations(id), proposed_date timestamp, comment_home text, comment_away text, created timestamp
);
create table if not exists public.darts_match_log (id bigint generated by default as identity primary key, match_id bigint references public.darts_matches(id), change_type text, old_value timestamp, new_value timestamp, old_text_value text, new_text_value text, changed_by text, changed_at timestamp default now());
create index if not exists darts_matches_comp_idx on public.darts_matches(competition_id, match_date);
-- Never grant direct access: player contacts and administrative actions remain server-side.
do $$ declare t text; begin
  foreach t in array array['darts_players','darts_competitions','darts_locations','darts_boards','darts_opening_hours','darts_blocked_days','darts_matches','darts_match_log'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;
grant usage, select on sequence public.darts_match_log_id_seq to service_role;

create table if not exists public.darts_accounts (
  player_id bigint primary key references public.darts_players(id), password_hash text not null,
  failed_attempts integer not null default 0, locked_until timestamptz
);
create table if not exists public.darts_sessions (
  token_hash text primary key, player_id bigint not null references public.darts_players(id), expires_at timestamptz not null
);
alter table public.darts_accounts enable row level security;
alter table public.darts_sessions enable row level security;
revoke all on public.darts_accounts, public.darts_sessions from anon, authenticated;
grant all on public.darts_accounts, public.darts_sessions to service_role;

-- All checks and the audit entry run in one transaction under a row lock.
create or replace function public.darts_update_match(p_match_id bigint, p_actor_id bigint, p_date timestamp, p_board bigint, p_score text, p_action text)
returns void language plpgsql security definer set search_path = public as $$
declare m darts_matches%rowtype; actor darts_players%rowtype; changed boolean; new_status text; home_ok boolean; away_ok boolean;
begin
  select * into actor from darts_players where id=p_actor_id and active=true;
  if not found then raise exception 'Účet není aktivní'; end if;
  select * into m from darts_matches where id=p_match_id for update;
  if not found then raise exception 'Zápas nebyl nalezen'; end if;
  if upper(actor.role) <> 'ADMIN' and not coalesce(actor.id = m.home_player or actor.id = m.away_player,false) then raise exception 'K tomuto zápasu nemáte přístup'; end if;
  if p_action not in ('save','approve','cancel') then raise exception 'Neplatná akce'; end if;
  if p_action='cancel' then
    update darts_matches set status='CANCELLED',approved_home=false,approved_away=false where id=m.id;
    insert into darts_match_log(match_id,change_type,old_text_value,new_text_value,changed_by) values(m.id,'STATUS',m.status,'CANCELLED',actor.name);
    return;
  end if;
  if p_action='approve' then
    if m.score is null or m.status='CANCELLED' then raise exception 'Schválit lze pouze odehraný zápas s výsledkem'; end if;
    if actor.id not in (m.home_player,m.away_player) then raise exception 'Výsledek schvalují hráči zápasu'; end if;
    home_ok := m.approved_home or actor.id=m.home_player; away_ok := m.approved_away or actor.id=m.away_player;
    update darts_matches set approved_home=home_ok,approved_away=away_ok,status=case when home_ok and away_ok then 'APPROVED' else 'PLAYED' end where id=m.id;
    insert into darts_match_log(match_id,change_type,new_text_value,changed_by) values(m.id,'APPROVAL','Potvrzení výsledku',actor.name);
    return;
  end if;
  p_score := nullif(trim(p_score),'');
  if p_score is not null and p_score !~ '^\d{1,2}:\d{1,2}$' then raise exception 'Výsledek zadejte ve tvaru 6:3'; end if;
  if p_board is not null and not exists(select 1 from darts_boards where id=p_board and location_id=m.location_id and active) then raise exception 'Neplatný terč'; end if;
  if p_date is not null and p_board is not null then perform pg_advisory_xact_lock(hashtextextended(p_board::text || ':' || p_date::text, 0)); end if;
  if (m.match_date is distinct from p_date or m.board_id is distinct from p_board or m.status='CANCELLED') and p_date is not null and p_board is not null and exists(select 1 from darts_matches where id<>m.id and board_id=p_board and match_date=p_date and coalesce(status,'')<>'CANCELLED') then raise exception 'Terč je v tomto termínu obsazen'; end if;
  if (m.match_date is distinct from p_date or m.board_id is distinct from p_board or m.status='CANCELLED') and p_date is not null and exists(select 1 from darts_blocked_days where location_id=m.location_id and (board_id is null or board_id=p_board) and p_date between blocked_from and blocked_to) then raise exception 'Termín je blokovaný'; end if;
  changed := m.match_date is distinct from p_date or m.board_id is distinct from p_board or m.score is distinct from p_score;
  home_ok := case when changed then false else m.approved_home end; away_ok := case when changed then false else m.approved_away end;
  new_status := case when p_score is not null then case when home_ok and away_ok then 'APPROVED' else 'PLAYED' end else 'PLANNED' end;
  if m.match_date is distinct from p_date then insert into darts_match_log(match_id,change_type,old_value,new_value,changed_by) values(m.id,'MATCH_DATE',m.match_date,p_date,actor.name); end if;
  if m.board_id is distinct from p_board then insert into darts_match_log(match_id,change_type,old_text_value,new_text_value,changed_by) values(m.id,'BOARD_ID',m.board_id::text,p_board::text,actor.name); end if;
  if m.score is distinct from p_score then insert into darts_match_log(match_id,change_type,old_text_value,new_text_value,changed_by) values(m.id,'SCORE',m.score,p_score,actor.name); end if;
  update darts_matches set match_date=p_date,board_id=p_board,score=p_score,approved_home=home_ok,approved_away=away_ok,status=new_status where id=m.id;
end $$;
revoke all on function public.darts_update_match(bigint,bigint,timestamp,bigint,text,text) from public, anon, authenticated;
grant execute on function public.darts_update_match(bigint,bigint,timestamp,bigint,text,text) to service_role;

create or replace function public.darts_sync_log_sequence() returns void language sql security definer set search_path=public as $$
  select setval(pg_get_serial_sequence('public.darts_match_log','id'), greatest(coalesce((select max(id) from public.darts_match_log),0),1), true);
$$;
revoke all on function public.darts_sync_log_sequence() from public, anon, authenticated;
grant execute on function public.darts_sync_log_sequence() to service_role;
